"""Frozen-source CPU attribution probe; numerical work only in fresh workers."""
from __future__ import annotations
import argparse, copy, cProfile, hashlib, json, os, platform, pstats, resource, statistics, subprocess, sys, time, warnings
from pathlib import Path
BASE=Path(__file__).resolve().parent

def digest(data):return hashlib.sha256(data).hexdigest()
def write(path,value):
    with path.open('x') as f:json.dump(value,f,indent=2,allow_nan=False)
def summary(rows):
    vals=[r['wall_seconds'] for r in rows]
    return {'median':statistics.median(vals),'min':min(vals),'max':max(vals),'cpu_median':statistics.median(r['cpu_seconds'] for r in rows)}
def condition():
    result={'utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'loadavg':list(os.getloadavg()),'pid':os.getpid()}
    for name,cmd in [('thermal',['pmset','-g','therm']),('power',['pmset','-g','batt'])]:
        p=subprocess.run(cmd,capture_output=True,text=True,timeout=5)
        result[name]={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
    return result

def worker(case_id,profile_enabled):
    import _threads as threads
    threads.bootstrap_cli()
    protocol=json.loads((BASE/'protocol.json').read_text())
    actual={str(p.relative_to(BASE/'source')):digest(p.read_bytes()) for p in sorted((BASE/'source').rglob('*.py'))}
    if actual!=protocol['source_files']:raise RuntimeError('Frozen source manifest changed')
    sys.path.insert(0,str(BASE/'source/src'))
    case=next(c for c in protocol['cases'] if c['id']==case_id)
    out=BASE/case_id
    out.mkdir()
    receipt={'case':case,'source_manifest_sha256':protocol['manifest_sha256'],'probe_sha256':digest(Path(__file__).read_bytes()),'start_condition':condition(),'runs':{},'profiles':{}}
    with warnings.catch_warnings(record=True) as caught:
      warnings.simplefilter('always')
      with threads.single_thread_policy() as policy:
        import numpy as np
        import scipy,scipy.linalg,scipy.sparse
        import torch
        import resdag as rd
        from resdag.training import ESNTrainer
        receipt['native_policy']=policy
        receipt['versions']={'python':sys.version,'torch':torch.__version__,'numpy':np.__version__,'scipy':scipy.__version__,'resdag':rd.__version__}
        def fp(x):
            if isinstance(x,torch.Tensor):
                x=x.detach().cpu()
                if x.layout!=torch.strided:x=x.to_dense()
                return {'shape':list(x.shape),'dtype':str(x.dtype),'sha256':digest(x.contiguous().numpy().tobytes())}
            if isinstance(x,np.ndarray):return {'shape':list(x.shape),'dtype':str(x.dtype),'sha256':digest(np.ascontiguousarray(x).tobytes())}
            if isinstance(x,dict):return {k:fp(v) for k,v in sorted(x.items())}
            if isinstance(x,(tuple,list)):return [fp(v) for v in x]
            if x is None or isinstance(x,(str,int,float,bool)):return x
            raise TypeError(type(x))
        def maxabs(x,y):return float(np.max(np.abs(np.asarray(x)-np.asarray(y))))
        def timed(fn):
            threads.verify_thread_policy()
            usage=resource.getrusage(resource.RUSAGE_SELF)
            cpu=time.process_time(); wall=time.perf_counter()
            value=fn()
            elapsed=time.perf_counter()-wall;cpu_elapsed=time.process_time()-cpu
            after=resource.getrusage(resource.RUSAGE_SELF)
            threads.verify_thread_policy()
            return value,{'wall_seconds':elapsed,'cpu_seconds':cpu_elapsed,'cpu_wall_ratio':cpu_elapsed/elapsed,'voluntary_switches':after.ru_nvcsw-usage.ru_nvcsw,'involuntary_switches':after.ru_nivcsw-usage.ru_nivcsw}
        params=protocol['recipe']
        class Gaussian:
            def __call__(self,n,seed=None):
                rng=np.random.default_rng(seed)
                return rng.standard_normal((n,n))*(rng.random((n,n))<params['mean_degree']/n)
        def build(sparse=False,radius=None):
            inp=rd.reservoir_input(3,dtype=torch.float64)
            features=rd.ESNLayer(case['n'],feedback_size=3,recurrent_initializer=Gaussian(),spectral_radius=radius,leak_rate=params['leak_rate'],feedback_initializer=('uniform',{'input_scaling':params['input_scaling']}),bias=True,bias_scaling=params['bias_scaling'],bias_initializer=('uniform',{'input_scaling':params['bias_scaling']}),seed=protocol['seed'],dtype=torch.float64,sparse=sparse)(inp)
            head=rd.RidgeReadoutLayer(case['n'],3,alpha=params['alpha'],bias=False,name='output').double()
            return rd.ESNModel(inp,head(features)).eval()
        with torch.no_grad():
            weights_path=BASE/f"weights-{case['n']}.pt"
            if not weights_path.exists():
                reference=build(False,params['spectral_radius'])
                torch.save(reference.state_dict(),weights_path)
            baseline=torch.load(weights_path,weights_only=True)
            raw=build(case['sparse'])
            raw.load_state_dict(baseline,strict=True)
            prototype=rd.Model(graph=raw,washout=case['washout']).eval()
            data_path=BASE/f"data-{case['id']}.pt"
            rng=np.random.default_rng(protocol['data_seed'])
            t=np.arange(case['observations'])[None,:,None]
            channel=np.arange(1,4)[None,None,:]
            batch=np.arange(case['b'])[:,None,None]
            values=np.sin(.013*t*channel+.17*batch)+.1*np.cos(.037*t+channel+.11*batch)+.003*rng.standard_normal((case['b'],case['observations'],3))
            observations=torch.tensor(values,dtype=torch.float64)
            torch.save(observations,data_path)
            history=observations[:,-case['history']:]
            receipt['artifacts']={'weights':{'path':str(weights_path),'sha256':digest(weights_path.read_bytes()),'state_dict':fp(baseline)},'observations':{'path':str(data_path),'sha256':digest(data_path.read_bytes()),'values':fp(observations)}}
            runs=[];expected=None
            for index in range(protocol['warmups']+protocol['repeats']):
                fitted=copy.deepcopy(prototype)
                _,fit_time=timed(lambda:fitted.fit(observations))
                prediction,forecast_time=timed(lambda:fitted.forecast(history=history,horizon=case['horizon'],compile=False))
                hashes={'fitted_state_dict':fp(fitted.state_dict()),'forecast':fp(prediction),'state':fp(fitted.get_state())}
                if expected is not None and hashes!=expected:raise RuntimeError('Repeated public workflow output changed')
                expected=hashes
                runs.append({'iteration':index,'warmup':index<protocol['warmups'],'fit':fit_time,'forecast':forecast_time})
            receipt['public_runs']=runs;receipt['public_hashes']=expected
            receipt['public_summary']={k:summary([r[k] for r in runs if not r['warmup']]) for k in ('fit','forecast')}
            torch.save({'fitted':fitted.state_dict(),'prediction':prediction,'state':fitted.get_state()},out/'public-final.pt')
            receipt['after_public_condition']=condition()
            reservoir=next(m for m in raw.modules() if isinstance(m,rd.BaseReservoirLayer))
            head=next(m for m in raw.modules() if isinstance(m,rd.RidgeReadoutLayer))
            fitted_head=next(m for m in fitted.modules() if isinstance(m,rd.RidgeReadoutLayer))
            scaled=fitted._scaled_inputs((observations[:,:-1],))[0]
            target=fitted.output_scalers[0](observations[:,1+case['washout']:])
            low_runs=[]
            for index in range(4):
                graph=copy.deepcopy(raw)
                _,row=timed(lambda:ESNTrainer(graph).fit(warmup_inputs=(scaled[:,:case['washout']],),train_inputs=(scaled[:,case['washout']:],),targets={'output':target}))
                low_runs.append(row)
            low_head=next(m for m in graph.modules() if isinstance(m,rd.RidgeReadoutLayer))
            receipt['lowlevel_fit']={'runs':low_runs[1:],'summary':summary(low_runs[1:]),'coefficient_maxabs_vs_public':maxabs(low_head.weight.numpy(),fitted_head.weight.numpy()),'boundary':'Same already-scaled stored inputs and exact graph weights; excludes workflow validation/scaling/transactional graph staging and commit.'}
            projected=reservoir.cell.project_inputs([scaled])
            weight=reservoir.cell.weight_hh
            dense=weight.to_dense() if weight.layout!=torch.strided else weight
            projected_np=projected.numpy();w_np=dense.numpy();w_csr=scipy.sparse.csr_matrix(w_np)
            leak=params['leak_rate']
            def recurrence(kind):
                if kind.startswith('torch'):
                    state=torch.zeros((case['b'],case['n']),dtype=torch.float64);outputs=[]
                    for i in range(projected.shape[1]):
                        p=projected[:,i,:]
                        if kind=='torch-cell':_,state=reservoir.cell.step(p,state)
                        elif kind=='torch-addmm':state=torch.lerp(state,torch.tanh(torch.addmm(p,state,dense.t())),leak)
                        elif kind=='torch-addmv':state=torch.lerp(state,torch.tanh(torch.addmv(p[0],dense,state[0])).unsqueeze(0),leak)
                        elif kind=='torch-mv-plus':state=torch.lerp(state,torch.tanh(p+torch.mv(dense,state[0]).unsqueeze(0)),leak)
                        outputs.append(state)
                    return torch.stack(outputs,dim=1)
                state=np.zeros((case['b'],case['n']),dtype=np.float64);outputs=np.empty((case['b'],projected.shape[1],case['n']))
                for i in range(projected.shape[1]):
                    rec=state@w_np.T if kind=='numpy-dense' else (w_csr@state.T).T
                    state=state+leak*(np.tanh(projected_np[:,i,:]+rec)-state)
                    outputs[:,i,:]=state
                return outputs
            kinds=['torch-cell','torch-addmm','numpy-dense','scipy-csr']
            if case['b']==1:kinds+=['torch-addmv','torch-mv-plus']
            reference_features=None
            for kind in kinds:
                rows=[];result=None
                for i in range(4):result,row=timed(lambda:recurrence(kind));rows.append(row)
                result_np=result.numpy() if isinstance(result,torch.Tensor) else result
                if kind=='torch-cell':reference_features=result
                receipt['runs'][kind]={'samples':rows[1:],'summary':summary(rows[1:]),'result':fp(result),'maxabs_vs_cell':maxabs(result_np,reference_features.numpy())}
            receipt['common_work']={'input':fp(scaled),'projected':fp(projected),'weight':fp(dense),'weight_strides':list(dense.stride()),'projected_strides':list(projected.stride()),'state_shape':[case['b'],case['n']],'nonzero_weights':int(torch.count_nonzero(dense)),'scope':'Identical preprojected streams, full sequence state collection; Torch uses exact same tanh+lerp as cell. NumPy/SciPy implement same equations with potentially different roundoff. Input projection and readout excluded.'}
            X=reference_features[:,case['washout']:].reshape(-1,case['n']);Y=target.reshape(-1,3)
            xnp=X.numpy();ynp=Y.numpy()
            def scipy_solve():
                gram=xnp.T@xnp;rhs=xnp.T@ynp
                gram.flat[::case['n']+1]+=params['alpha']
                return scipy.linalg.cho_solve(scipy.linalg.cho_factor(gram,lower=True,check_finite=False),rhs,check_finite=False)
            for label,fn in [('torch_ridge_with_guards',lambda:head.solve(X,Y)[0]),('scipy_direct_without_guards',scipy_solve)]:
                rows=[]
                for i in range(4):coefs,row=timed(fn);rows.append(row)
                receipt['runs'][label]={'samples':rows[1:],'summary':summary(rows[1:]),'coefficients':fp(coefs),'boundary':'Shared exact X,Y; SciPy omits ResDAG safety diagnostics and fallback. Both form Gram/RHS and direct Cholesky solve.'}
            receipt['before_profiles_condition']=condition()
            if profile_enabled:
                for operation in ['fit','forecast']:
                    obj=copy.deepcopy(prototype) if operation=='fit' else fitted
                    fn=(lambda:obj.fit(observations)) if operation=='fit' else (lambda:obj.forecast(history=history,horizon=case['horizon'],compile=False))
                    profiler=cProfile.Profile();profiler.enable();result,row=timed(fn);profiler.disable();profiler.dump_stats(str(out/f'{operation}.pstats'))
                    stats=pstats.Stats(profiler)
                    entries=[]
                    for (file,line,function),(cc,nc,tt,ct,callers) in stats.stats.items():entries.append({'file':file,'line':line,'function':function,'primitive_calls':cc,'calls':nc,'self_seconds':tt,'cumulative_seconds':ct})
                    write(out/f'{operation}-cprofile.json',{'timing':row,'entries':sorted(entries,key=lambda x:x['cumulative_seconds'],reverse=True)})
                    obj=copy.deepcopy(prototype) if operation=='fit' else fitted
                    fn=(lambda:obj.fit(observations)) if operation=='fit' else (lambda:obj.forecast(history=history,horizon=case['horizon'],compile=False))
                    with torch.profiler.profile(activities=[torch.profiler.ProfilerActivity.CPU],record_shapes=False,profile_memory=True) as prof:
                        result,row=timed(fn)
                    entries=[{'key':e.key,'count':e.count,'self_cpu_us':e.self_cpu_time_total,'total_cpu_us':e.cpu_time_total,'self_cpu_memory_bytes':e.self_cpu_memory_usage,'total_cpu_memory_bytes':e.cpu_memory_usage} for e in prof.key_averages()]
                    write(out/f'{operation}-torch-profile.json',{'timing':row,'entries':sorted(entries,key=lambda x:x['self_cpu_us'],reverse=True),'warning':'Profiler timings include instrumentation and are attribution only; memory counters are operator allocations, not peak process residency.'})
                    receipt['profiles'][operation]=row
                    del prof
            threads.verify_thread_policy()
            origins={name:str(Path(mod.__file__).resolve()) for name,mod in sys.modules.items() if name=='resdag' or name.startswith('resdag.') if getattr(mod,'__file__',None)}
            if any(not p.startswith(str(BASE/'source/src/resdag')) for p in origins.values()):raise RuntimeError('Source isolation violation')
            receipt['import_origins']=origins
      receipt['warnings']=[{'category':w.category.__name__,'message':str(w.message),'filename':w.filename,'lineno':w.lineno} for w in caught]
    receipt['end_condition']=condition()
    write(out/'result.json',receipt)
    print(json.dumps({'case':case_id,'public':receipt['public_summary'],'primitives':{k:v['summary'] for k,v in receipt['runs'].items()}}),flush=True)

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--worker');parser.add_argument('--no-profile',action='store_true');args=parser.parse_args()
    if args.worker:return worker(args.worker,not args.no_profile)
    protocol=json.loads((BASE/'protocol.json').read_text())
    write(BASE/'launch.json',{'executable':sys.executable,'probe_sha256':digest(Path(__file__).read_bytes()),'start':condition()})
    for case in protocol['cases']:
        with (BASE/f"{case['id']}.stdout.txt").open('x') as stdout,(BASE/f"{case['id']}.stderr.txt").open('x') as stderr:
            started=time.perf_counter();p=subprocess.run([sys.executable,str(Path(__file__).resolve()),'--worker',case['id']],stdout=stdout,stderr=stderr,timeout=1800)
        print(case['id'],p.returncode,time.perf_counter()-started,flush=True)
        if p.returncode:raise RuntimeError('Worker failed; retained stderr and all prior evidence')
    write(BASE/'complete.json',{'cases':{c['id']:json.loads((BASE/c['id']/'result.json').read_text()) for c in protocol['cases']},'end':condition()})
if __name__=='__main__':main()

